<summary>PoC - complete integration test (149 lines; safe code, no `unsafe`; source comments are in Chinese, code is unmodified)</summary>

````rust
//! F4 PoC - `surrealkv 0.21.2`：`InternalKeyRef` 解码缺少长度前置条件（safe 公共 API ⇒
//! release 越界读 / debug panic）
//!
//! Analysis: `../F4-surrealkv-internal-key-unchecked-decode.md`.
//!
//! `surrealkv` 是 SurrealDB 的持久化 KV 引擎（`kv-surrealkv` / `surrealkv://`，默认存储
//! 选项之一；`surrealdb/core/Cargo.toml:35,76`）。其 crate 根部公开导出
//! `InternalKeyRef<'a>`（`surrealkv-0.21.2/src/lib.rs:905-907`）与安全构造函数
//! `from_encoded`（`:911-916`）：
//!
//! ```text
//! pub fn from_encoded(encoded: &'a [u8]) -> Self {
//!     debug_assert!(encoded.len() >= 16);      // 唯一的“检查”，release 下被编译掉
//!     Self { encoded }
//! }
//! ```
//!
//! 访问器随后对长度做**无检查减法**：
//!
//! * `user_key()`  → `&encoded[..encoded.len() - 16]`（safe 切片，短切片会 panic）
//! * `seq_num()`   → `trailer_from_encoded` → `let n = encoded.len() - 16; read_u64_be(encoded, n)`
//! * `trailer()`   → 同上
//! * `timestamp()` → `let n = encoded.len() - 8; read_u64_be(encoded, n)`
//!
//! `read_u64_be`（`:696-702`）是：
//!
//! ```text
//! unsafe { u64::from_be_bytes(*(buffer.as_ptr().add(offset) as *const [u8; 8])) }
//! ```
//!
//! 因此长度 < 16（`user_key` 之外还要求 < 8 才会命中 `timestamp`）时：
//!
//! * debug 构建：`enc.len() - 16` 触发 `attempt to subtract with overflow`（或先命中
//!   `from_encoded` 的 `debug_assert!`）⇒ panic（DoS）；
//! * **release 构建：减法回绕为 `usize::MAX - k`，`add` 回绕到 `base - k`，
//!   8 字节读落在分配之前 ⇒ 越界读（UB）**。ASan 期望报
//!   `heap-buffer-overflow ... READ of size 8`，帧落在 `InternalKeyRef::timestamp`
//!   / `read_u64_be`。
//!
//! 同一条不变量也缺失在盘上解码边界：`sstable/block.rs::seek_next_entry`
//!（`:684-736`）只校验 `key_end`/`value_end` 不超过 `restart_offset`，不校验重建出的
//! `current_key.len() >= 16`；`BlockIterator::key()`（`:792-795`）把它直接包成
//! `InternalKeyRef`。SurrealDB 的 surrealkv 包装层在版本化读路径上**直接**调用
//! `key_ref.timestamp()`（`surrealdb/core/src/kvs/surrealkv/mod.rs:510-514,906-909,
//! 934-938,964-967,992-998`），比 `user_key()` 先命中无检查减法。
//!
//! # Integration（放在**已有**目录，无需 mkdir、无需改 `Cargo.toml`/`mod.rs`）
//!
//! 目标仓库已有集成测试目录 `<surrealdb>/surrealdb/core/tests/`（与 F1/F2 PoC 相同；
//! `tests/*.rs` 自动发现）。`surrealkv` 是 `surrealdb-core` 的可选依赖，由特性
//! `kv-surrealkv` 启用（`surrealdb/core/Cargo.toml:35,76`），因此 integration test
//! 可直接 `use surrealkv::InternalKeyRef;`。文件级 `#![cfg(feature = "kv-surrealkv")]`
//! 保证未启用该特性时测试目标为空、不影响其他构建。
//!
//! ```text
//! cp findings/surrealdb/PoC/f4_surrealkv_internal_key_oob.rs \
//!    <surrealdb>/surrealdb/core/tests/f4_surrealkv_internal_key_oob.rs
//! ```
//!
//! # Running
//!
//! ```text
//! # 1) dev profile：对照组 + “唯一防线是 debug_assert”的确定性证据
//! cargo test -p surrealdb-core --features kv-surrealkv \
//!   --test f4_surrealkv_internal_key_oob -- --nocapture
//!
//! # 2) release + ASan：越界读（正确 oracle）
//! RUSTFLAGS="-Zsanitizer=address" ASAN_OPTIONS=detect_leaks=0 \
//!   cargo +nightly-2026-04-14 test --release \
//!   --target x86_64-unknown-linux-gnu -p surrealdb-core --features kv-surrealkv \
//!   --test f4_surrealkv_internal_key_oob -- --ignored --nocapture --test-threads=1
//! ```
//!
//! 说明：OOB 测试在 release 下才存在（`#[cfg(not(debug_assertions))]`），因为 debug
//! 构建会先在 `from_encoded` 的 `debug_assert!` 处 panic；`--release` 关闭该断言后，
//! 无检查减法与越界读才会发生。不加 ASan 时该测试可能“静默通过”（读到垃圾值），
//! 不构成缺陷不存在的反证。

#![cfg(feature = "kv-surrealkv")]
#![allow(dead_code)]

use surrealkv::InternalKeyRef;

// ===========================================================================
// 对照组：合法编码的 internal key 必须能被正确解码（证明 PoC 自身可用）
// ===========================================================================

/// `InternalKey` 的线格式：`user_key || trailer_be(8) || timestamp_be(8)`，
/// `trailer = (seq_num << 8) | kind`，因此最小合法长度是 16 字节（空 user key）。
/// 这里用已知值构造并验证 `user_key()` / `seq_num()` / `timestamp()` 的往返。
#[test]
fn valid_encoded_key_round_trips() {
	let user_key = b"user-key";
	let seq: u64 = 0x00AB_CDEF;
	let kind: u8 = 2; // InternalKeyKind::Set
	let timestamp: u64 = 123_456_789;

	let mut encoded = Vec::with_capacity(user_key.len() + 16);
	encoded.extend_from_slice(user_key);
	encoded.extend_from_slice(&((seq << 8) | kind as u64).to_be_bytes());
	encoded.extend_from_slice(&timestamp.to_be_bytes());
	assert_eq!(encoded.len(), 24);

	let key = InternalKeyRef::from_encoded(&encoded);
	assert_eq!(key.user_key(), b"user-key".as_slice());
	assert_eq!(key.seq_num(), seq);
	assert_eq!(key.timestamp(), timestamp);
}

// ===========================================================================
// 探针 A（debug）：`from_encoded` 的唯一防线是 debug-only 断言
// ===========================================================================

/// 15 字节切片 < 16。debug 构建中 `from_encoded` 的 `debug_assert!` 立即 panic；
/// release 构建中该断言被编译掉，构造函数“成功”返回 -- 这正是缺失的运行时前置条件。
/// 该测试只在 debug 构建存在（release 下不会 panic，不能让 `#[should_panic]` 失败）。
#[cfg(debug_assertions)]
#[test]
#[should_panic(expected = "encoded.len() >= 16")]
fn short_slice_is_rejected_only_by_debug_assert() {
	let buf = [0u8; 15];
	let _key = InternalKeyRef::from_encoded(&buf);
}

// ===========================================================================
// 探针 B（release + ASan）：短切片 → `len - 8` / `len - 16` 下溢 → 越界读
// ===========================================================================

/// release 构建下：
///
/// * `let n = std::hint::black_box(4usize);` 让长度成为运行期值，避免被常量折叠；
/// * `timestamp()` 计算 `n - 8` → `usize::MAX - 3`，`add` 回绕到 `base - 4`，
///   读 8 字节 ⇒ **越界读**（ASan: heap-buffer-overflow READ of size 8）；
/// * `seq_num()` 计算 `n - 16` → `base - 12`，同样越界读。
///
/// 该测试在 debug 构建中被 `cfg` 排除（那里会先 panic）。
#[cfg(not(debug_assertions))]
#[test]
#[ignore = "heap-buffer-overflow READ of size 8; run with --release under ASan"]
fn short_slice_timestamp_and_seq_num_oob_read() {
	// Keep the length opaque so the underflow/pointer arithmetic is emitted at runtime.
	let n = std::hint::black_box(4usize);
	let v = vec![0u8; n];
	let key = InternalKeyRef::from_encoded(&v[..n]); // no runtime check in release

	let ts = key.timestamp(); // encoded.len() - 8  -> base - 4
	let seq = key.seq_num(); // encoded.len() - 16 -> base - 12
	println!("ts={ts} seq={seq}");
}

````

</details>

